// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;
    function setUp() public { c = new PredictTheBlockHashChallenge{value: 1 ether}(); }

    function testFuzz_property(address actor, bytes32 guessHash) public {
        vm.assume(actor != address(0) && actor != address(this));
        vm.deal(actor, 3 ether);

        // Round 1: lock in a guess and settle it.
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(guessHash);

        vm.roll(block.number + 2); // past the target block
        vm.prank(actor);
        c.settle();

        // Rule: after settling, the same player may lock in a NEW guess.
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        bool ok;
        try c.lockInGuess{value: 1 ether}(guessHash) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok, "after settle, lockInGuess must succeed again");
    }
}
